import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';
import './Header.css';

const Header = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
      setIsMobileMenuOpen(false);
    }
  };

  return (
    <header className={`dark-header ${isScrolled ? 'scrolled' : ''}`}>
      <div className="header-content">
        <div className="logo-container" onClick={() => scrollToSection('hero')}>
          <span className="logo-text">ZeroTaskIA</span>
        </div>

        <nav className={`dark-nav ${isMobileMenuOpen ? 'mobile-open' : ''}`}>
          <a className="dark-nav-link" onClick={() => scrollToSection('services')}>
            Servicios
          </a>
          <a className="dark-nav-link" onClick={() => scrollToSection('about')}>
            Nosotros
          </a>
          <a className="dark-nav-link" onClick={() => scrollToSection('process')}>
            Cómo Trabajamos
          </a>
          <button className="btn-primary" onClick={() => scrollToSection('contact')}>
            Contacto
          </button>
        </nav>

        <button 
          className="mobile-menu-btn"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>
    </header>
  );
};

export default Header;